 const customers=Array.from({length:13},(_,i)=>({id:'CONTACT-'+i,tenantId:f.hq,name:'Contact '+i,phone:'13900000'+String(i).padStart(3,'0'),names:['Contact '+i],batches:[],calls:[],callCount:0,batchCount:0,unknownDurationCount:0,totalDurationSeconds:0,followup:{}}));
 b.CustomerDirectory={...b.CustomerDirectory,list:()=>customers,find:id=>customers.find(c=>c.id===id),status:()=>({}),at:c=>c.createdAt||'',result:()=>'',duration:()=>'',dispositionLabel:()=>''};
