 const fakeNode={isConnected:true,focus(){},querySelectorAll(){return[]},addEventListener(){},get outerHTML(){return html},set outerHTML(value){html=value;parse(value)}};
 function element(id){if(!el.has(id))el.set(id,{value:'',disabled:false,checked:false,dataset:{},isConnected:true,selectedOptions:[],textContent:'',querySelectorAll(){return[]},querySelector(){return null},addEventListener(){},focus(){this.focused=true}});return el.get(id)}
 function parse(markup){for(const m of markup.matchAll(/<(input|select|textarea|button)\b[^>]*id="([^"]+)"[^>]*>/g)){const e=element(m[2]),value=/\bvalue="([^"]*)"/.exec(m[0])?.[1];if(value!==undefined)e.value=value;}}
 b.document={getElementById:id=>el.get(id)||null,querySelector:selector=>html.includes('customer-directory-page')?fakeNode:null,querySelectorAll:()=>[],addEventListener(){},createElement:()=>({textContent:'',get innerHTML(){return esc(this.textContent)}})};
 b.PlatformUI={escape:esc,pageHeader:(t,d,a='')=>'<div class="page-title-row"><h1>'+esc(t)+'</h1><p>'+esc(d)+'</p>'+a+'</div>',table:(cols,rows,o={})=>'<table>'+rows.map(r=>'<tr>'+cols.map(c=>'<td>'+(c.render?c.render(r[c.key],r):esc(r[c.key]))+'</td>').join('')+'</tr>').join('')+'</table>'+(o.footer||''),pagination:(total,page,size,handler)=>'<nav data-total="'+total+'" data-page="'+page+'">'+handler+'</nav>',toolbar:(a,b)=>a+b,openLayer:(id,markup)=>{layers.set(id,markup);return{}},closeLayer:id=>layers.delete(id),help:()=>'',detailSection:(a,b)=>a+b};
 function render(options={}){opts=options;html=b.Pages['customer-directory'].render(options);parse(html);renders.push({options,html});return html}
