const tests=[];function test(name,fn){const count=assertions;try{fn();tests.push({name,status:'pass',assertions:assertions-count})}catch(e){tests.push({name,status:'fail',assertions:assertions-count,error:e.stack})}}
function tabs(h){return [...h.matchAll(/<button\b(?=[^>]*role="tab")[^>]*>[\s\S]*?<\/button>/g)].map(m=>m[0])}
function seedBusiness(x){x.f.bindPlan();for(let i=0;i<13;i++){const p=x.f.input('BIZ-'+i);p.rows[0].fields.name='Business '+i;p.rows[0].fields.phone='13800000'+String(i).padStart(3,'0');p.importBasisToken=success(x.f.s.previewImport(p)).importBasisToken;success(x.f.s.importRecords(p,{requestId:crypto.randomUUID()}));}}
test('both views share one title and semantic, enabled tabs with a linked panel',()=>{const x=attach();for(const view of ['business','contacts']){const h=x.render({fourNodeDirectoryView:view,preserveFilters:true}),t=tabs(h);eq(t.length,2,'two semantic tabs');eq(t.filter(t=>t.includes('aria-selected="true"')).length,1,'one selected');assert(t.every(t=>!/\sdisabled(?:[\s=>])/.test(t)),'active tab not disabled');eq((h.match(/<h1>客户档案<\/h1>/g)||[]).length,1,'one stable page heading');assert(h.includes('role="tabpanel"'),'panel role');const selected=t.find(t=>t.includes('aria-selected="true"')),id=/\bid="([^"]+)"/.exec(selected)?.[1],controlled=/aria-controls="([^"]+)"/.exec(selected)?.[1];assert(!!id&&!!controlled,'tab id and controls');assert(h.includes('id="'+controlled+'"')&&h.includes('aria-labelledby="'+id+'"'),'linked active panel');assert(h.indexOf('<h1>客户档案</h1>')<h.indexOf('role="tablist"'),'title precedes tabs');}});
test('switching view preserves native contact filters and page',()=>{const x=attach();x.render({fourNodeDirectoryView:'contacts',preserveFilters:true});x.set('directory-keyword','Contact');x.set('directory-contact','uncalled');x.set('directory-source','直接联系');x.b.Pages['customer-directory'].query();x.b.Pages['customer-directory'].setPage(2);const before=x.b.Pages['customer-directory'].captureNavigationState();x.b.FourNodeWorkspace.setDirectoryView('business');x.b.FourNodeWorkspace.setDirectoryView('contacts');const after=x.b.Pages['customer-directory'].captureNavigationState();for(const key of ['keyword','contactFilter','sourceFilter','page'])eq(after[key],before[key],key+' retained');assert(x.calls.slice(-2).every(c=>c.options.preserveFilters===true),'switch explicitly preserves filters');assert(x.html().includes('value="Contact"'),'query input retained');});
test('business query/page restore from captured state',()=>{const x=attach();seedBusiness(x);x.render({fourNodeDirectoryView:'business'});x.set('fnw-directory-keyword','Business');x.b.FourNodeWorkspace.queryBusinessDirectory();x.b.FourNodeWorkspace.setDirectoryPage(2);const before=x.b.Pages['customer-directory'].captureNavigationState();assert(x.html().includes('data-page="2"'),'second business page');x.set('fnw-directory-keyword','NO-MATCH');x.b.FourNodeWorkspace.queryBusinessDirectory();x.b.Pages['customer-directory'].restoreNavigationState(before);const h=x.render({preserveFilters:true});assert(h.includes('value="Business"'),'business keyword restored');assert(h.includes('data-page="2"'),'business page restored');});
test('identity changes reset directory state rather than lending previous tenant filters',()=>{const x=attach();seedBusiness(x);x.render({fourNodeDirectoryView:'business'});x.set('fnw-directory-keyword','Business');x.b.FourNodeWorkspace.queryBusinessDirectory();x.b.FourNodeWorkspace.setDirectoryPage(2);x.f.switchTo('ADMIN-STORE');const h=x.render({preserveFilters:true});assert(h.includes('id="fnw-directory-keyword" value=""'),'tenant switch clears business keyword');assert(h.includes('data-page="1"'),'tenant switch resets business page');});
test('native contact detail opening and followup refresh retain integrated wrapper',()=>{const x=attach();x.render({customerId:'CONTACT-0',preserveFilters:true});x.b.Pages['customer-directory'].init({customerId:'CONTACT-0'});assert(x.layers.get('customer-directory-detail')?.includes('Contact 0'),'original contact drawer opens');x.b.Pages['customer-directory'].refreshSummary();const h=x.html();eq(tabs(h).length,2,'followup summary refresh retains tabs');eq((h.match(/<h1>客户档案<\/h1>/g)||[]).length,1,'refresh retains one header');assert(h.includes('role="tabpanel"'),'refresh retains panel');});
test('active tabs do not redraw input drafts; keyboard directions move selection and focus',()=>{const x=attach();x.render({fourNodeDirectoryView:'contacts',preserveFilters:true});x.set('directory-keyword','未提交草稿');const count=x.calls.length;x.b.FourNodeWorkspace.setDirectoryView('contacts',true);eq(x.calls.length,count,'active tab does not navigate');eq(x.element('directory-keyword').value,'未提交草稿','active tab preserves unsubmitted input');assert(x.element('fnw-directory-tab-contacts').focused,'active tab focus retained');let prevented=0;const key=(key,current)=>{x.b.FourNodeWorkspace.directoryTabKey({key,preventDefault(){prevented++}},current);x.b.Pages['customer-directory'].init({});};key('ArrowRight','contacts');assert(x.html().includes('id="fnw-directory-tab-business"')&&tabs(x.html()).some(t=>t.includes('id="fnw-directory-tab-business"')&&t.includes('aria-selected="true"')),'ArrowRight wraps to business');assert(x.element('fnw-directory-tab-business').focused,'keyboard business focus');key('End','business');assert(tabs(x.html()).some(t=>t.includes('id="fnw-directory-tab-contacts"')&&t.includes('aria-selected="true"')),'End selects contacts');key('Home','contacts');assert(tabs(x.html()).some(t=>t.includes('id="fnw-directory-tab-business"')&&t.includes('aria-selected="true"')),'Home selects business');key('ArrowLeft','business');assert(tabs(x.html()).some(t=>t.includes('id="fnw-directory-tab-contacts"')&&t.includes('aria-selected="true"')),'ArrowLeft wraps to contacts');const before=x.calls.length;key('Escape','contacts');eq(x.calls.length,before,'unhandled keys do not navigate');eq(prevented,4,'only supported direction keys prevented');});
test('new customer detail request wins over remembered business view',()=>{const x=attach();x.render({customerId:'CONTACT-0',fourNodeDirectoryView:'business',preserveFilters:true});x.b.Pages['customer-directory'].init({customerId:'CONTACT-0',fourNodeDirectoryView:'business'});assert(tabs(x.html()).some(t=>t.includes('id="fnw-directory-tab-contacts"')&&t.includes('aria-selected="true"')),'explicit customer request selects contacts');assert(x.layers.get('customer-directory-detail')?.includes('Contact 0'),'explicit requested customer opens');});
